const icon=(name,cls='')=>`<img class="${cls}" src="${A}icons/${name}" alt="">`;
function go(r){
  if(r==='login') projectMenuOpen=false;
  if(r==='projects') projectMenuOpen=true;
  location.hash=r;
}
function shell(body,active='dashboard') {const projectArea=['projects','project-detail','buildings','units','unit-detail','import-preview','import-result','create-project','new-project'].includes(active),handoverArea=['handover','handover-detail','handover-team','handover-schedule','handover-email','handover-form','handover-notifications'].includes(active),notificationPage=active==='handover-notifications',detail=active==='project-detail',building=active==='buildings',unitList=active==='units',unitDetail=active==='unit-detail',handoverDetail=['handover-detail','handover-team','handover-schedule','handover-email','handover-form'].includes(active),importPage=active.startsWith('import-')||active==='create-project'||active==='new-project',showProjectSubnav=projectMenuOpen,navActive=projectArea?(building||unitList||unitDetail?'':'projects'):notificationPage?'announcements':handoverArea?'handover':active;return `<div class="app"><aside class="side"><div class="side-logo"><img src="${A}logo-sidebar.png"><img src="${A}sidebar-wordmark.svg"></div><div class="nav-section">${nav.slice(0,1).map(n=>navItem(n,navActive)).join('')}</div><small>BẤT ĐỘNG SẢN</small>${navItem(nav[1],navActive)}${showProjectSubnav?projectSubnav(active):''}${nav.slice(2,5).map(n=>navItem(n,navActive)).join('')}<small>VẬN HÀNH</small>${nav.slice(5).map(n=>navItem(n,navActive)).join('')}<footer>Version 1.0.0<br>© 2026 Novaland Group</footer></aside><div class="workspace"><header class="header"><button class="hamb">${icon('menu.svg')}</button>${projectArea?`<div class="header-crumb"><span>${building?'Dashboard':'Tổng quan'}</span><i>/</i><span>Dự án</span>${detail?'<i>/</i><b>Chi tiết dự án</b>':building?'<i>/</i><b>Phân khu/tháp</b>':unitList||unitDetail?'<i>/</i><b>Sản phẩm</b>':importPage?`<i>/</i><b>${active==='create-project'||active==='new-project'?'Tạo dự án':active==='import-result'?'Kết quả Import':'Preview dữ liệu'}</b>`:''}</div>`:handoverArea?`<div class="header-crumb"><span>Tổng quan</span><i>/</i><span>Bàn giao</span>${notificationPage?'<i>/</i><b>Thông báo bàn giao</b>':handoverDetail?'<i>/</i><b>Chi tiết đợt BG-2026-001</b>':''}</div>`:''}<label class="global-search">${icon('search.svg')}<input placeholder="${handoverArea?'Tìm kiếm mã đợt, tên dự án...':'Search project name, code, investor, ...'}"></label><div class="notify">${icon('notification.svg')}<b>6</b></div><img class="avatar" src="${A}profile.png"><div class="profile"><strong>Kenny Wang</strong><span>${handoverArea&&!handoverDetail?'Business development':'Project Admin'}</span></div></header><main class="main ${detail?'project-detail-main':building?'building-main':unitList?'units-main':unitDetail?'unit-detail-main':importPage?'import-main':handoverArea?'handover-main':projectArea?'projects-main':''}">${body}</main></div></div>`}
function navItem(n,a){const enabled=['dashboard','projects','handover'].includes(n[0]),route=n[0];return `<button class="nav ${a===n[0]?'on':''}"${enabled?` data-go="${route}"`:' aria-disabled="true"'}>${icon(n[1])}<span>${n[2]}</span>${['projects'].includes(n[0])?'<i>⌄</i>':''}</button>`}
function projectSubnav(active){return `<nav class="project-subnav"><button class="${active==='buildings'?'active':''}" data-go="buildings">Phân khu/tháp</button><button class="${active==='units'||active==='unit-detail'?'active':''}" data-go="units">Sản phẩm</button><button>Tài sản & Tiện ích</button></nav>`}
function login(){return `<div class="login"><section class="hero"><div class="login-brand"><img src="${A}logo-login.png"><img src="${A}login-wordmark.svg"></div><h1>One platform. All Operations.</h1><p>Empowering real estate developers and operations teams to<br>manage projects, assets and communities efficiently</p><div class="benefits">${[['project.svg','Project Management','Plan, track and deliver projects with transparency'],['residents.svg','Resident & Communities','Deliver excellent service and engage communities'],['facility.svg','Asset & Facility Management','Manage assets throughout their life cycle and performance'],['insights.svg','Data & insights','Make data driven decision with real-times insights']].map(x=>`<div>${icon(x[0])}<span><b>${x[1]}</b><small>${x[2]}</small></span></div>`).join('')}</div></section><section class="login-side"><div class="language"><span>◎</span><b>Tiếng Việt</b><i>⌄</i></div><form id="login"><header><h2>Chào mừng trở lại !</h2><p>Đăng nhập để truy cập Nova Operation Management Platform</p></header><button type="button" class="ms">${icon('microsoft.svg')}Đăng nhập với Microsoft</button><div class="or"><span>Hoặc đăng nhập</span></div><div class="login-fields">${field('Email','Example@company.com','mail.svg','email')}${field('Mật khẩu','Nhập mật khẩu','lock.svg','password')}<div class="remember"><label><input type="checkbox"> Keep me signed in</label><a>Quên mật khẩu</a></div><button class="submit">${icon('login.svg')}Đăng nhập</button></div></form><footer>${icon('support.svg')}Cần hỗ trợ? Liên hệ <b>Bộ phận IT</b></footer></section></div>`}
function field(label,ph,ic,type){return `<label class="field">${label} <em>*</em><div>${icon(ic)}<input type="${type}" placeholder="${ph}" required>${type==='password'?icon('eye.svg','eye'):''}</div></label>`}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function controls(){return `<div class="controls"><button>${icon('calendar.svg')}<span>This Month: 1 - 31 May 2024</span><i aria-hidden="true"></i></button><button>${icon('filter.svg')}<span>Bộ lọc</span><i aria-hidden="true"></i></button></div>`}
function stat(label,val,note,ic,color){return `<article class="stat"><div><span>${label}</span><b>${val}</b><small>${note}</small></div><i style="--c:${color}">${icon(ic)}</i></article>`}
function dashboard(investor=false){const stats=investor?[['Total Projects','24','3 Upcoming Handover','building.svg','#29b765'],['Total Investment','24,560','↑ 8.5% vs last month','building.svg','#367cf5'],['Total Units','18,256','↑ 5.4% vs last month','client.svg','#a448e5'],['Total Assets','37,842','↑ 6.7% vs last month','calendar.svg','#ff9300'],['Total Land Bank','312.5','↑ 2.1% vs last month','building.svg','#1da7ba'],['Portfolio Occupancy','78%','↑ 3% vs last month','chart.svg','#078c48']]:[['Dự án của tôi','8','2 Sắp bàn giao','my-project.svg','#2bbd65'],['Tiến độ tổng thể','68%','<mark>+ 6%</mark> so với tháng trước','chart.svg','#087ef5'],['Yêu cầu công việc','324','189 Hoàn thành  ·  95 Đang xử lý','toolbox.svg','#ff8a00'],['Ngân sách so với Thực tế','92%','Theo kế hoạch (128.6B / 118.3B VND)','wallet.svg','#b84df2'],['Sự cố','12','5 Cao  ·  4 Vừa  ·  3 thấp','alert.svg','#ff3b30']];return shell(`${pageHead(investor?'Good morning Kenny Wang!':'Chào Kenny Wang!',investor?"Here's what happen across your project today":'Dưới đây là những gì đã diễn ra trong dự án của bạn ngày hôm nay.',controls())}<section class="stats ${investor?'six':''}">${stats.map(x=>stat(...x)).join('')}</section><section class="dash-grid"><article class="card progress-card"><h3>${investor?'Investment by Project Status':'Tổng quan tiến độ dự án'}</h3>${donut(investor?'24,560':'49',investor?'Billion VND':'Projects','projects')}</article><article class="card trend-card"><h3>${investor?'Investment Trend':'Xu hướng tiến độ'}</h3>${chart()}</article><article class="card orders-card"><h3>${investor?'Investment by Asset Class':'Lệnh công việc theo trạng thái'}</h3>${donut(investor?'24,560':'324',investor?'Billion VND':'Total','orders')}</article>${investor?miniList('Portfolio by Region'):milestones()}${dataCard(investor?'Project Status Overview':'Công việc quá hạn')}${investor?miniList('Financial Summary'):tasks()}</section>`, 'dashboard')}
function donut(v,s,type='projects'){const rows=type==='orders'?[['Completed','189 (58%)'],['In Progress','95 (29%)'],['Overdue','40 (13%)']]:[['Completed','18 (37%)'],['In Progress','21 (43%)'],['At Risk','6 (12%)'],['Not Started','4 (8%)']];return `<div class="donut ${type}"><div><b>${v}</b><small>${s}</small></div><ul>${rows.map(x=>`<li><span>${x[0]}</span><b>${x[1]}</b></li>`).join('')}</ul></div><a>${type==='orders'?'Xem tất cả lệnh công việc':'Xem tất cả dự án'} →</a>`}
function chart(){return `<div class="chart"><div class="chart-legend"><span>This Month</span><span>Last Month</span></div><div class="chart-y"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><svg viewBox="0 0 600 170" preserveAspectRatio="none"><polyline points="0,120 80,105 150,96 200,70 250,82 320,52 390,37 460,42 530,25 600,5"/><polyline class="dash" points="0,145 80,135 150,112 210,122 280,91 350,99 420,70 500,75 600,52"/><circle cx="320" cy="52" r="5"/></svg><div class="chart-tip"><b>15 May 2024</b><span>This Month: 68%</span><em>Last Month: 54%</em></div><div class="axis"><span>May 1</span><span>May 8</span><span>May 15</span><span>May 22</span><span>May 31</span></div></div>`}
function milestones(){const rows=[['shield.svg','Handover - The Stella','Handover Phase','15'],['milestone-building.svg','Podium Completion - The Elite','Construction Phase','22'],['milestone-eye.svg','Facade Inspection - The Valencia','Quality Check','28'],['flame.svg','Fire System Testing - Grand Villas','MEP Phase','31']];return `<article class="card milestone-card"><h3>Các cột mốc sắp tới ${icon('calendar-clock.svg')}</h3>${rows.map(x=>`<div><i>${icon(x[0])}</i><span><b>${x[1]}</b><small>${x[2]}</small></span><em><b>${x[3]}</b><small>MAY</small></em></div>`).join('')}<a>Xem tất cả các cột mốc →</a></article>`}
function tasks(){const rows=[['Review monthly progress report','Aqua City - The Elite','Hôm nay'],['Approve material submittals','The Valencia','Ngày mai'],['Prepare client meeting presentation','The Grand Villas','16 May'],['Site visit and inspection','The Stella','17 May']];return `<article class="card task-card"><h3>Công việc của tôi ${icon("check-square.svg")}</h3>${rows.map(x=>`<div><i></i><span><b>${x[0]}</b><small>${x[1]}</small></span><em>${x[2]}</em></div>`).join('')}<a>Xem tất cả các công việc →</a></article>`}
function miniList(title){return `<article class="card list"><h3>${title}</h3>${['Aqua City - The Elite','The Stella','The Valencia','Grand Villas'].map((x,i)=>`<div><i>${icon(['shield.svg','milestone-building.svg','milestone-eye.svg','flame.svg'][i])}</i><span><b>${x}</b><small>${['Handover Phase','Construction Phase','Quality Check','MEP Phase'][i]}</small></span><em>${[15,22,28,31][i]} MAY</em></div>`).join('')}<a>View all →</a></article>`}
function dataCard(title){const vi=title==='Công việc quá hạn';return `<article class="card table-mini"><h3>${title}${vi?icon('alert-triangle.svg'):''}</h3><table><thead><tr><th>${vi?'Mã công việc':'Work Order'}</th><th>${vi?'Dự án':'Project'}</th><th>${vi?'Ngày hết hạn':'Due Date'}</th><th>${vi?'Ưu tiên':'Priority'}</th></tr></thead><tbody>${projectRows.map((r,i)=>`<tr><td>WO-2024-${1256-i*67}</td><td>${r[1]}</td><td>02/08/2026</td><td><span>${i<2?'High':'Medium'}</span></td></tr>`).join('')}</tbody></table><a>${vi?'Xem tất cả các công việc quá hạn':'View all'} →</a></article>`}
function listing(type){const cfg=type==='projects'?['Projects','Manage and monitor all real estate projects across developers and property management companies.',projectRows,['Project code','Project','Investor','Ops Entity','Location','Status','Buildings','Units','Handover','Occupancy']]:type==='buildings'?['Buildings','Manage buildings and capacity across every project.',projectRows,['Code','Building','Investor','Ops Entity','Location','Status','Floors','Units','Handover','Occupancy']]:['Handover','Track apartment handovers and readiness status.',projectRows,['Code','Project','Investor','Ops Entity','Location','Status','Buildings','Units','Handover','Occupancy']];return shell(`${pageHead(cfg[0],cfg[1],`<div><button class="ghost">Edit</button><button class="green">＋ Add ${cfg[0]}</button></div>`)}${filters()}${table(cfg[2],cfg[3],type==='projects'?'project':'')}`,type==='handover'?'handover':'projects')}
