function formField(label,value,kind='input',required=false,disabled=false){const off=disabled?' disabled':'',area=label.startsWith('Diện tích'),clean=area?value.replace(/\s*m²$/,''):value;return `<label class="${area?'area-field':''}"><span class="field-caption">${label}${required?' <em>*</em>':''}</span>${kind==='select'?`<select${off}><option>${clean}</option></select>`:`<input value="${clean}"${off}>${area?'<i class="area-unit">m<sup>2</sup></i>':''}`}</label>`}
function blankField(label,placeholder,kind='input',required=false){const area=label.startsWith('Diện tích');return `<label class="${area?'area-field':''}"><span class="field-caption">${label}${required?' <em>*</em>':''}</span>${kind==='select'?`<select><option value="">${placeholder}</option></select>`:`<input placeholder="${placeholder}">${area?'<i class="area-unit">m<sup>2</sup></i>':''}`}</label>`}
