function render(){let r=location.hash.slice(1)||'login';if(r==='login')projectMenuOpen=false;const views={login,dashboard:()=>dashboard(false),investor:()=>dashboard(true),projects:projectList,buildings:buildingList,handover:handoverList,'handover-detail':handoverDetail,'handover-team':handoverTeamTab,'handover-schedule':handoverScheduleTab,'handover-email':handoverEmailTab,'handover-form':handoverFormTab,'handover-notifications':handoverNotifications,'create-notification':createHandoverNotification,'handover-plan':handoverPlan,'handover-plan-detail':handoverPlanDetail,units,project:projectDetail,unit:unitDetail,'create-project':createProject,'new-project':newProject,'import-preview':importPreview,'import-result':importResult};if(!views[r])r='dashboard';document.querySelector('#app').innerHTML=views[r]();const language=document.querySelector('.language');if(language)language.innerHTML=`${icon('globe.svg')}<b>Tiếng Việt</b>${icon('expand-more.svg')}`;document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));document.querySelector('#login')?.addEventListener('submit',e=>{e.preventDefault();go('dashboard')});document.querySelector('.ms')?.addEventListener('click',()=>go('dashboard'));document.querySelector('.hamb')?.addEventListener('click',()=>document.querySelector('.side').classList.toggle('open'));document.querySelector('.new-project')?.addEventListener('click',()=>go('new-project'));document.querySelector('.import-project')?.addEventListener('click',()=>{document.body.insertAdjacentHTML('beforeend',importModal());bindImport()});document.querySelectorAll('.save-project').forEach(x=>x.onclick=()=>go('projects'))}
function bindImport(){document.querySelectorAll('.close-import').forEach(x=>x.onclick=()=>document.querySelector('.import-overlay')?.remove());const input=document.querySelector('#excel-file'),name=document.querySelector('#import-name'),next=document.querySelector('.continue-import'),drop=document.querySelector('.drop-zone');let hasFile=false;const validate=()=>next.disabled=!(hasFile&&name.value.trim());const selected=fileName=>{hasFile=true;drop.querySelector('span').innerHTML=`Đã chọn: <b>${fileName}</b>`;validate()};name.oninput=validate;input.onchange=()=>input.files.length&&selected(input.files[0].name);drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length)selected(e.dataTransfer.files[0].name)};next.onclick=()=>{document.querySelector('.import-overlay')?.remove();go('create-project')}}
document.addEventListener('click',e=>{
  const planCalendar=e.target.closest('.plan-modal-fields label>span img');
  if(planCalendar){
    const picker=planCalendar.parentElement.querySelector('.handover-date-picker');
    if(picker?.showPicker)picker.showPicker();else picker?.focus();
    return;
  }
  const createBatch=e.target.closest('.create-handover');
  if(createBatch&&location.hash==='#handover'){
    document.body.insertAdjacentHTML('beforeend',handoverPlanModal());
    return;
  }
  if(e.target.closest('.close-handover-plan')){
    document.querySelector('.handover-plan-overlay')?.remove();
    return;
  }
  if(e.target.closest('.handover-plan-next')){
    document.querySelector('.handover-plan-overlay')?.remove();
    go('handover-plan');
    return;
  }
  const menuTrigger=e.target.closest('.batch-menu-trigger');
  if(menuTrigger){
    e.stopPropagation();
    const menu=menuTrigger.parentElement.querySelector('.batch-dropdown');
    document.querySelectorAll('.batch-dropdown.open').forEach(x=>{if(x!==menu)x.classList.remove('open')});
    menu?.classList.toggle('open');
    return;
  }
  const menuOption=e.target.closest('.batch-dropdown button');
  if(menuOption){
    const menu=menuOption.closest('.batch-dropdown');
    menu.querySelectorAll('button').forEach(x=>{x.classList.remove('selected');x.querySelector('span')?.remove()});
    menuOption.classList.add('selected');
    menu.classList.remove('open');
    return;
  }
  document.querySelectorAll('.batch-dropdown.open').forEach(x=>x.classList.remove('open'));
  if(!e.target.matches('.field .eye'))return;
  const input=e.target.closest('.field')?.querySelector('input');
  if(input)input.type=input.type==='password'?'text':'password';
});
function showPlanFile(file){const drop=document.querySelector('.plan-drop'),name=drop?.querySelector('.plan-file-name');if(!drop||!name||!file)return;name.textContent=file.name;drop.classList.add('has-file')}
document.addEventListener('change',e=>{
  if(e.target.matches('.plan-file-input')&&e.target.files?.[0])showPlanFile(e.target.files[0]);
  const table=e.target.closest('.new-detail-table');
  if(!table||!e.target.matches('.select-all-units,.select-unit'))return;
  const selectAll=table.querySelector('.select-all-units');
  const units=[...table.querySelectorAll('.select-unit')];
  if(e.target===selectAll)units.forEach(unit=>unit.checked=selectAll.checked);
  const selected=units.filter(unit=>unit.checked).length;
  selectAll.checked=selected===units.length&&units.length>0;
  selectAll.indeterminate=selected>0&&selected<units.length;
});
document.addEventListener('dragover',e=>{const drop=e.target.closest('.plan-drop');if(!drop)return;e.preventDefault();drop.classList.add('dragging')});
document.addEventListener('dragleave',e=>e.target.closest('.plan-drop')?.classList.remove('dragging'));
document.addEventListener('drop',e=>{const drop=e.target.closest('.plan-drop');if(!drop)return;e.preventDefault();drop.classList.remove('dragging');const file=e.dataTransfer?.files?.[0];if(file){const input=drop.querySelector('.plan-file-input');try{const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files}catch{}showPlanFile(file)}});
function syncPlanDetailHeader(){const route=location.hash,crumb=document.querySelector('.header-crumb b');if(route==='#create-notification'){if(crumb)crumb.textContent='Tạo thông báo';return}if(route!=='#handover-plan-detail')return;const name=document.querySelector('.profile strong'),role=document.querySelector('.profile span');if(name)name.textContent='Peter Nguyễn';if(role)role.textContent='PMD';if(crumb)crumb.textContent='Lập kế hoạch BG'}
addEventListener('hashchange',render);addEventListener('hashchange',syncPlanDetailHeader);render();syncPlanDetailHeader();
